package com.oyuki.marketsquare.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="market_states") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class State { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=100) private String name; @Column(nullable=false) @Builder.Default private boolean active=true; }